final_contents.tests/drivers/sensor/ina228/boards/nativ:
&i2c0 {
    compatible = "zephyr,i2c-emul-controller";
    status = "okay";

    ina228_default_test: ina228@40 {
        compatible = "ti,ina228";
        reg = <0x40>;
        rshunt-micro-ohms = <16200>;
        current-lsb-microamps = <19>;
        status = "okay";
        label = "INA228_DEFAULT_TEST";
    };
};

